settings.custom_css:
selector .ak-cert-in { --width: 100%; width: 100%; max-width: 619px; }
/* color de acento plano */
selector .ak-oro-text .elementor-heading-title, selector .ak-cert-title .ak-g { background-image: linear-gradient(#DD0005, #DD0005); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-card { border-color: transparent !important; background: linear-gradient(#F3F5F7, #F3F5F7) padding-box, linear-gradient(#DD0005, #DD0005) border-box !important; }
selector .ak-cert-btn .elementor-button { border-image: linear-gradient(#DD0005, #DD0005) 1 !important; }
selector .ak-cert-btn .elementor-button-text, selector .ak-cert-btn .elementor-button-icon i { background-image: linear-gradient(#DD0005, #DD0005); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-cert-btn .elementor-button:hover { background-image: linear-gradient(#DD0005, #DD0005) !important; }
selector .ak-cert-btn .elementor-button:hover .elementor-button-text, selector .ak-cert-btn .elementor-button:hover .elementor-button-icon i { -webkit-text-fill-color: #060606; }
selector .ak-medal img { display: block; width: 32px; height: auto; }
selector .ak-cert-title .elementor-heading-title { white-space: nowrap; }
selector .ak-card { --width: 100%; width: 100%; }
selector .ak-card-body { --width: auto; width: auto; flex: 1 1 auto; min-width: 0; }
selector .ak-cert-btn .elementor-button { width: auto; min-width: 340px; height: 68px; display: inline-flex; align-items: center; justify-content: center; gap: 16px; padding: 0 36px; }
selector .elementor-widget-text-editor p { margin: 0; }
@media (max-width: 1366px) {
  selector .ak-cert-btn .elementor-button { min-width: 280px; height: 58px; padding: 0 30px; }
}
selector .ak-mb { display: none; }
@media (max-width: 767px) {
  selector .ak-mb { display: inline; }
  selector .ak-dk { display: none; }
  selector .ak-cert-title .elementor-heading-title { white-space: normal; }
  selector .ak-cert-btn .elementor-button { min-width: 220px; height: 44px; padding: 0 22px; gap: 12px; }
}
/* Pantalla completa (desktop y laptop): la sección mide lo que queda bajo el header fijo y todo el bloque
   de la derecha se escala en proporción con --u (1 px del diseño original). Mismos espacios y colores, solo más chico si la pantalla es baja. */
@media (min-width: 1025px) {
  selector { min-height: calc(100vh - 90px) !important; --u: min(1px, calc((100vh - 90px) / 960)); }
  /* el panel de la imagen nunca es más ancho que 1.1 veces su alto: así el certificado no se recorta */
  selector > .ak-cert-img { --width: 50%; width: 50% !important; background-position: 50% 52.5% !important; }
  selector > .ak-cert-txt { --width: auto; width: auto !important; flex: 1 1 0 !important; }
  selector > .ak-cert-txt { padding: calc(var(--u) * 71) calc(var(--u) * 60) calc(var(--u) * 71) calc(var(--u) * 60) !important; justify-content: center !important; }
  selector .ak-cert-in { max-width: calc(var(--u) * 619); }
  selector .ak-cert-in { margin-right: calc(max(0px, 100% - var(--u) * 619) / 2 + var(--u) * 60) !important; }
  selector .ak-oro-text .elementor-heading-title { font-size: calc(var(--u) * 20) !important; letter-spacing: calc(var(--u) * 2) !important; }
  selector .ak-cert-title { margin-top: calc(var(--u) * 3) !important; }
  selector .ak-cert-title .elementor-heading-title { font-size: calc(var(--u) * 50) !important; }
  selector .ak-cert-p { margin-top: calc(var(--u) * 41) !important; }
  selector .ak-cert-p, selector .ak-cert-p p { font-size: calc(var(--u) * 20) !important; }
  selector .ak-card { padding: calc(var(--u) * 24) calc(var(--u) * 24) calc(var(--u) * 24) calc(var(--u) * 24) !important; gap: calc(var(--u) * 18) !important; }
  selector .ak-cert-in > .ak-card:nth-of-type(1), selector .ak-cert-p + .ak-card { margin-top: calc(var(--u) * 36) !important; }
  selector .ak-card + .ak-card { margin-top: calc(var(--u) * 20) !important; }
  selector .ak-medal { padding-top: calc(var(--u) * 4) !important; }
  selector .ak-medal img { width: calc(var(--u) * 32) !important; }
  selector .ak-card-body { gap: calc(var(--u) * 6) !important; }
  selector .ak-card-body .elementor-heading-title { font-size: calc(var(--u) * 20) !important; }
  selector .ak-card-body .elementor-widget-text-editor, selector .ak-card-body .elementor-widget-text-editor p { font-size: calc(var(--u) * 20) !important; }
  selector .ak-cert-btn { margin-top: calc(var(--u) * 16) !important; }
  selector .ak-cert-btn .elementor-button { width: auto !important; min-width: calc(var(--u) * 340) !important; height: calc(var(--u) * 68) !important; padding: 0 calc(var(--u) * 36) !important; gap: calc(var(--u) * 16) !important; font-size: calc(var(--u) * 16) !important; letter-spacing: calc(var(--u) * 1.44) !important; }
}
@media (min-width: 1025px) and (max-width: 1366px) {
  selector { min-height: calc(100vh - 80px) !important; --u: min(1px, calc((100vh - 80px) / 791)); }
  selector > .ak-cert-img { --width: 50%; width: 50% !important; background-position: 50% 52.5% !important; }
  selector > .ak-cert-txt { padding: calc(var(--u) * 56) calc(var(--u) * 48) calc(var(--u) * 56) calc(var(--u) * 48) !important; }
  selector .ak-cert-in { max-width: calc(var(--u) * 619); }
  selector .ak-cert-in { margin-right: calc(max(0px, 100% - var(--u) * 619) / 2 + var(--u) * 48) !important; }
  selector .ak-oro-text .elementor-heading-title { font-size: calc(var(--u) * 16) !important; letter-spacing: calc(var(--u) * 1.8) !important; }
  selector .ak-cert-title { margin-top: calc(var(--u) * 24) !important; }
  selector .ak-cert-title .elementor-heading-title { font-size: calc(var(--u) * 42) !important; }
  selector .ak-cert-p { margin-top: calc(var(--u) * 22) !important; }
  selector .ak-cert-p, selector .ak-cert-p p { font-size: calc(var(--u) * 17) !important; }
  selector .ak-card { padding: calc(var(--u) * 26) calc(var(--u) * 20) calc(var(--u) * 24) calc(var(--u) * 20) !important; gap: calc(var(--u) * 18) !important; }
  selector .ak-cert-in > .ak-card:nth-of-type(1), selector .ak-cert-p + .ak-card { margin-top: calc(var(--u) * 26) !important; }
  selector .ak-card + .ak-card { margin-top: calc(var(--u) * 18) !important; }
  selector .ak-medal { padding-top: calc(var(--u) * 4) !important; }
  selector .ak-medal img { width: calc(var(--u) * 32) !important; }
  selector .ak-card-body { gap: calc(var(--u) * 6) !important; }
  selector .ak-card-body .elementor-heading-title { font-size: calc(var(--u) * 17) !important; }
  selector .ak-card-body .elementor-widget-text-editor, selector .ak-card-body .elementor-widget-text-editor p { font-size: calc(var(--u) * 17) !important; }
  selector .ak-cert-btn { margin-top: calc(var(--u) * 22) !important; }
  selector .ak-cert-btn .elementor-button { width: auto !important; min-width: calc(var(--u) * 280) !important; height: calc(var(--u) * 58) !important; padding: 0 calc(var(--u) * 30) !important; gap: calc(var(--u) * 14) !important; font-size: calc(var(--u) * 14) !important; letter-spacing: calc(var(--u) * 1.44) !important; }
}
selector .ak-cert-btn .elementor-button-text { white-space: nowrap; }
@media (max-width: 767px) {
  selector .ak-cert-btn, selector .ak-cert-btn .elementor-button-wrapper { width: 100%; }
  selector .ak-cert-btn .elementor-button { min-width: 0 !important; width: 100% !important; height: auto !important; min-height: 44px; padding: 10px 14px !important; }
  selector .ak-cert-btn .elementor-button-text { white-space: normal !important; text-align: center; }
}
